/* English build of picker.js — generated by cli/i18n.php, do not edit */
/*
 * اختيار مستلمين بأعينهم: Search by name or Username or Number, and Select from النتائج, والمختارون رقائق قابلة للإزالة.
 *   [data-picker data-url="Link البحث" data-name="pick[]" data-selected='[...]']
 *     [data-picker-type="نوع"] أزرار الأنواع (optional)   [data-picker-q] Field البحث
 *     [data-picker-chips] المختارون   [data-picker-results] النتائج   [data-picker-count] عددهم
 *     [data-picker-all] Select all results   [data-picker-clear] Clear selection
 * عند Every تغيير يُطلق Event picker:change on العنصر.
 */
(function (document) {
  'use strict';
  document.querySelectorAll('[data-picker]').forEach(function (root) {
    var url = root.getAttribute('data-url');
    var name = root.getAttribute('data-name') || 'pick[]';
    var q = root.querySelector('[data-picker-q]');
    var chips = root.querySelector('[data-picker-chips]');
    var list = root.querySelector('[data-picker-results]');
    var counter = root.querySelector('[data-picker-count]');
    var types = root.querySelectorAll('[data-picker-type]');
    var type = types.length ? types[0].getAttribute('data-picker-type') : '';
    var picked = {};
    var order = [];
    var shown = [];
    var timer = null;
    var seq = 0;

    function el(tag, cls, text) { var e = document.createElement(tag); if (cls) { e.className = cls; } if (text !== undefined) { e.textContent = text; } return e; }
    function changed() {
      counter.textContent = SN.fmtNum(order.length);
      root.classList.toggle('has-picks', order.length > 0);
      root.dispatchEvent(new CustomEvent('picker:change', { bubbles: true, detail: { count: order.length } }));
    }
    function renderChips() {
      chips.innerHTML = '';
      order.forEach(function (id) {
        var it = picked[id];
        var c = el('span', 'picker-chip');
        c.appendChild(el('b', '', it.label));
        c.appendChild(el('span', 'picker-chip-phone', it.phone));
        var x = el('button', 'picker-chip-x');
        x.type = 'button';
        x.setAttribute('aria-label', 'Remove ' + it.label);
        x.innerHTML = SN.icon('x');
        x.addEventListener('click', function () { toggle(it, false); });
        c.appendChild(x);
        var h = el('input');
        h.type = 'hidden'; h.name = name; h.value = id;
        c.appendChild(h);
        chips.appendChild(c);
      });
    }
    function toggle(it, on) {
      if (on && !picked[it.id]) { picked[it.id] = it; order.push(it.id); }
      if (!on && picked[it.id]) { delete picked[it.id]; order = order.filter(function (x) { return x !== it.id; }); }
      renderChips();
      list.querySelectorAll('input[type=checkbox]').forEach(function (cb) { cb.checked = !!picked[cb.value]; });
      changed();
    }
    function renderList(items) {
      shown = items;
      list.innerHTML = '';
      if (!items.length) { list.appendChild(el('div', 'picker-empty', 'No results')); return; }
      items.forEach(function (it) {
        var row = el('label', 'picker-row');
        var cb = el('input');
        cb.type = 'checkbox'; cb.value = it.id; cb.checked = !!picked[it.id];
        cb.addEventListener('change', function () { toggle(it, cb.checked); });
        var main = el('span', 'picker-row-main');
        main.appendChild(el('b', '', it.label));
        main.appendChild(el('small', '', it.sub));
        row.appendChild(cb);
        row.appendChild(main);
        row.appendChild(el('span', 'picker-row-phone', it.phone));
        list.appendChild(row);
      });
    }
    function search() {
      clearTimeout(timer);
      timer = setTimeout(function () {
        var my = ++seq;
        list.classList.add('is-loading');
        var params = new URLSearchParams({ q: q.value.trim() });
        if (type) { params.set('type', type); }
        fetch(url + '?' + params, { headers: { Accept: 'application/json' }, credentials: 'same-origin' })
          .then(function (r) { return r.json(); })
          .then(function (d) { if (my === seq) { renderList(d.items || []); } })
          .catch(function () { if (my === seq) { list.innerHTML = ''; list.appendChild(el('div', 'picker-empty', 'Could not connect to the server.')); } })
          .then(function () { if (my === seq) { list.classList.remove('is-loading'); } });
      }, 250);
    }

    q.addEventListener('input', search);
    q.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); } });
    types.forEach(function (b) {
      b.addEventListener('click', function () {
        type = b.getAttribute('data-picker-type');
        types.forEach(function (x) { x.classList.toggle('is-active', x === b); x.setAttribute('aria-pressed', x === b ? 'true' : 'false'); });
        search();
      });
    });
    var all = root.querySelector('[data-picker-all]');
    if (all) { all.addEventListener('click', function () { shown.forEach(function (it) { toggle(it, true); }); }); }
    var clear = root.querySelector('[data-picker-clear]');
    if (clear) { clear.addEventListener('click', function () { order.slice().forEach(function (id) { toggle(picked[id], false); }); }); }
    try { JSON.parse(root.getAttribute('data-selected') || '[]').forEach(function (it) { picked[it.id] = it; order.push(it.id); }); } catch (e) { /* لا شيء */ }
    renderChips();
    changed();
    search();
  });
})(document);
